WITH structural_safety AS (
SELECT ws."loc_link", ROUND(((100 - ws."structLoadPct") / 100 * CASE WHEN ws."snowLoad_kgm2" > 100 OR ws."windSpeed_ms" > 20 THEN 0.5 WHEN ws."snowLoad_kgm2" > 50 OR ws."windSpeed_ms" > 10 THEN 0.8 ELSE 1.0 END)::numeric, 2) AS ssf FROM "WeatherAndStructure" ws
)
SELECT e."EQUIP_CODE" AS equipment_code, e."EquipType" AS equipment_type, (ce."cabin_env_snapshot" -> 'hvac' ->> 'heater_state') AS heater_status, tswg."insulationStat" AS insulation_status, ls."emerLightStat" AS emergency_light_status, ss.ssf, CASE WHEN ss.ssf > 0.7 AND (ce."cabin_env_snapshot" -> 'hvac' ->> 'heater_state') != 'Off' AND tswg."insulationStat" NOT IN ('Poor', 'Good') AND ls."emerLightStat" IN ('Testing', 'On') THEN 'Extreme Weather Ready' ELSE 'Not Ready' END AS ewr_status FROM "Equipment" e LEFT JOIN "CabinEnvironment" ce ON e."EQUIP_CODE" = ce."equipRef" LEFT JOIN "LightingAndSafety" ls ON e."EQUIP_CODE" = ls."equipRef" LEFT JOIN "Communication" c ON e."EQUIP_CODE" = c."equipRef" LEFT JOIN "ThermalSolarWindAndGrid" tswg ON c."COMM_ID" = tswg."comm_link" LEFT JOIN structural_safety ss ON ce."loc_link" = ss."loc_link" WHERE ss.ssf IS NOT NULL;

SELECT 
 cv."CHASSIS_ID", 
 ( 
 1 - ( 
 ( 
 (cv.ground_vehicle_status -> 'brake_system' ->> 'pad_wear_pct')::REAL + 
 (cv.ground_vehicle_status -> 'tracks' ->> 'wear_pct')::REAL 
 ) / 200.0 
 ) 
 ) * 
 ( 
 ( 
 NULLIF( 
 substring(cv.ground_vehicle_status -> 'vehicle_motion' ->> 'speed_kmh' from '^[0-9\.]+'), 
 '' 
 )::REAL * 3.6 / 50.0 
 ) 
 ) * 
 ( 
 (ef.engine_fluids_snapshot -> 'engine_core' ->> 'load_pct')::REAL / 100.0 
 ) AS VPC 
 FROM 
 "ChassisAndVehicle" AS cv 
 LEFT JOIN 
 "EngineAndFluids" AS ef 
 ON cv."engine_link" = ef."ENGINE_ID";

WITH FacilityResourceScores AS (
    SELECT fac_key, CASE com_res WHEN 'Comprehensive' THEN 3 WHEN 'Extensive' THEN 3 WHEN 'Adequate' THEN 2 WHEN 'Limited' THEN 1 ELSE 0 END AS resource_score FROM facilities WHERE com_res IS NOT NULL
), ResourceSupportedFacilities AS (
    SELECT fac_key FROM FacilityResourceScores WHERE resource_score >= 2
), PatientMetrics AS (
    SELECT e.pat_ref AS pat_key, e.clin_id, e.fac_id, COALESCE(tb.crisis_int, 0) AS crisis_int, COALESCE(e.miss_appt, 0) AS miss_appt FROM encounters e LEFT JOIN treatmentbasics tb ON e.enc_key = tb.enc_ref WHERE e.clin_id IS NOT NULL AND e.fac_id IN (SELECT fac_key FROM ResourceSupportedFacilities)
), ClinicianAvgMetrics AS (
    SELECT clin_id, fac_id, SUM(crisis_int) / NULLIF(COUNT(DISTINCT pat_key), 0)::DECIMAL AS avg_cif, SUM(miss_appt) / NULLIF(COUNT(DISTINCT pat_key), 0)::DECIMAL AS avg_mar FROM PatientMetrics GROUP BY clin_id, fac_id
), ClinicianPSM AS (
    SELECT clin_id, fac_id, ROUND(1.0 / (1.0 + COALESCE(avg_cif, 0) + COALESCE(avg_mar, 0))::NUMERIC, 2) AS psm FROM ClinicianAvgMetrics
)
SELECT clin_id, fac_id, psm, RANK() OVER (PARTITION BY fac_id ORDER BY psm DESC, clin_id) AS rank_within_facility FROM ClinicianPSM ORDER BY fac_id, rank_within_facility LIMIT 100
